// One email per leaver with a manager; someone without a manager is left to the administrators (the agents show as
// suspended in Landbright → Agents).
const event = $('Someone was deactivated').first().json;
const agents = event.data.agentsSuspended ?? [];
return $input.all()
  .map((item) => item.json)
  .filter((p) => p.manager && p.manager.email)
  .map((p) => ({
    to: p.manager.email,
    toName: p.manager.displayName,
    subject: `${p.displayName}'s agents need a new sponsor`,
    text: [
      `Hi ${p.manager.displayName.split(' ')[0]},`,
      '',
      `${p.displayName} was deactivated in Landbright${event.data.reason ? ` (${event.data.reason})` : ''}.`,
      `${agents.length === 1 ? 'An agent they sponsored is' : `${agents.length} agents they sponsored are`} suspended until someone takes ${agents.length === 1 ? 'it' : 'them'} over:`,
      'a Landbright administrator gives it a new sponsor and resumes it (Agents). Until then it gets no tokens.',
      '',
      `Agent ids: ${agents.join(', ')}`,
    ].join('\n'),
  }));
